pub fn snapshot_receipt_object_parse(stdout: String) -> Rc<SnapshotReceiptObjectParse> {
    {
        let lines = Rc::new(stdout.clone().split(&"\n".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let walked = lines.iter().cloned().fold(Rc::new(SnapshotReceiptObjectHeaderWalk {
    seen: false,
    header: "".to_string(),
    body_parts: Rc::new(vec![]),
}), |acc: Rc<SnapshotReceiptObjectHeaderWalk>, line: String| if !acc.seen.clone() {
            Rc::new(SnapshotReceiptObjectHeaderWalk {
    seen: true,
    header: line.clone(),
    body_parts: Rc::new(vec![]),
})
        } else {
            Rc::new(SnapshotReceiptObjectHeaderWalk {
    seen: true,
    header: acc.header.clone(),
    body_parts: v1_rt::concat(acc.body_parts.clone(), Rc::new(vec![line.clone()])),
})
        });
if !walked.seen.clone() {
            Rc::new(SnapshotReceiptObjectParse::SnapshotReceiptObjectParseRefused {
    detail: "the receipt object produced no metadata line".to_string(),
})
        } else {
            {
                let fields = Rc::new(walked.header.clone().split(&"|".to_string()).map(|s| s.to_string()).collect::<Vec<_>>());
let collected = fields.iter().cloned().fold(Rc::new(SnapshotReceiptObjectFieldWalk {
    n: 0,
    kind_word: "".to_string(),
    file_owner: "".to_string(),
    file_mode_octal: "".to_string(),
}), |acc: Rc<SnapshotReceiptObjectFieldWalk>, field: String| if (acc.n.clone() == 0) {
                    Rc::new(SnapshotReceiptObjectFieldWalk {
    n: 1,
    kind_word: field.clone(),
    file_owner: acc.file_owner.clone(),
    file_mode_octal: acc.file_mode_octal.clone(),
})
                } else {
                    if (acc.n.clone() == 1) {
                        Rc::new(SnapshotReceiptObjectFieldWalk {
    n: 2,
    kind_word: acc.kind_word.clone(),
    file_owner: field.clone(),
    file_mode_octal: acc.file_mode_octal.clone(),
})
                    } else {
                        if (acc.n.clone() == 2) {
                            Rc::new(SnapshotReceiptObjectFieldWalk {
    n: 3,
    kind_word: acc.kind_word.clone(),
    file_owner: acc.file_owner.clone(),
    file_mode_octal: field.clone(),
})
                        } else {
                            Rc::new(SnapshotReceiptObjectFieldWalk {
    n: v1_rt::int_add(acc.n.clone(), 1),
    kind_word: acc.kind_word.clone(),
    file_owner: acc.file_owner.clone(),
    file_mode_octal: acc.file_mode_octal.clone(),
})
                        }
                    }
                });
if (collected.n.clone() != 3) {
                    Rc::new(SnapshotReceiptObjectParse::SnapshotReceiptObjectParseRefused {
    detail: walked.header.clone(),
})
                } else {
                    Rc::new(SnapshotReceiptObjectParse::SnapshotReceiptObjectParsed {
    kind_word: collected.kind_word.clone(),
    file_owner: collected.file_owner.clone(),
    file_mode_octal: collected.file_mode_octal.clone(),
    bytes: walked.body_parts.clone().join(&"\n".to_string()),
})
                }
}
        }
}
}

